import { test, expect } from '@playwright/test';

test.describe('WebSocket Real-Time UI Updates', () => {
  let wsServer: any;
  const WS_PORT = 8765;
  const WS_URL = `ws://localhost:${WS_PORT}`;

  test.beforeEach(async ({ page }) => {
    // Mock WebSocket server setup
    await page.addInitScript(() => {
      (window as any).mockWebSocketMessages = [];
      (window as any).receivedMessages = [];
    });

    // Navigate to the application
    await page.goto('about:blank');

    // Inject WebSocket client code
    await page.addScriptTag({
      content: `
        class MockWebSocket extends EventTarget {
          constructor(url) {
            super();
            this.url = url;
            this.readyState = 1;
            this.onopen = null;
            this.onmessage = null;
            this.onerror = null;
            this.onclose = null;

            setTimeout(() => {
              if (this.onopen) this.onopen();
              this.dispatchEvent(new Event('open'));
            }, 100);
          }

          send(data) {
            window.mockWebSocketMessages.push(data);
          }

          close() {
            this.readyState = 3;
            if (this.onclose) this.onclose();
          }

          simulateMessage(data) {
            const event = new MessageEvent('message', { data });
            if (this.onmessage) this.onmessage(event);
            this.dispatchEvent(event);
          }
        }

        window.WebSocket = MockWebSocket;
      `
    });

    // Inject HTML with WebSocket connection and UI
    await page.setContent(`
      <!DOCTYPE html>
      <html>
      <head>
        <title>WebSocket Real-Time Updates</title>
      </head>
      <body>
        <div id="status">Disconnected</div>
        <div id="message-count">Messages: 0</div>
        <ul id="messages-list"></ul>
        <input type="text" id="message-input" placeholder="Enter message" />
        <button id="send-button">Send</button>

        <script>
          let messageCount = 0;
          let ws = null;

          function connectWebSocket() {
            ws = new WebSocket('ws://localhost:8765');

            ws.onopen = function() {
              document.getElementById('status').textContent = 'Connected';
              document.getElementById('status').setAttribute('data-connected', 'true');
            };

            ws.onmessage = function(event) {
              messageCount++;
              document.getElementById('message-count').textContent = 'Messages: ' + messageCount;

              const li = document.createElement('li');
              li.textContent = event.data;
              li.className = 'message-item';
              document.getElementById('messages-list').appendChild(li);
            };

            ws.onerror = function() {
              document.getElementById('status').textContent = 'Error';
              document.getElementById('status').setAttribute('data-connected', 'false');
            };

            ws.onclose = function() {
              document.getElementById('status').textContent = 'Disconnected';
              document.getElementById('status').setAttribute('data-connected', 'false');
            };
          }

          document.getElementById('send-button').addEventListener('click', function() {
            const input = document.getElementById('message-input');
            if (ws && input.value) {
              ws.send(input.value);
              input.value = '';
            }
          });

          connectWebSocket();
        </script>
      </body>
      </html>
    `);
  });

  test('should establish WebSocket connection and update status', async ({ page }) => {
    // Wait for connection to be established
    const statusElement = page.getByText('Connected');
    await expect(statusElement).toBeVisible({ timeout: 5000 });

    // Verify status attribute
    const status = page.locator('#status');
    await expect(status).toHaveAttribute('data-connected', 'true');
  });

  test('should receive real-time messages and update UI', async ({ page }) => {
    // Wait for connection
    await expect(page.getByText('Connected')).toBeVisible({ timeout: 5000 });

    // Get WebSocket instance and simulate incoming messages
    await page.evaluate(() => {
      const ws = (window as any).WebSocket.prototype;
      const wsInstance = new (window as any).WebSocket('ws://localhost:8765');
      (window as any).testWs = wsInstance;
    });

    // Simulate receiving messages
    await page.evaluate(() => {
      (window as any).testWs.simulateMessage('Hello from server');
    });

    // Verify message appears in the list
    await expect(page.getByText('Hello from server')).toBeVisible({ timeout: 5000 });

    // Verify message count updated
    await expect(page.getByText('Messages: 1')).toBeVisible();
  });

  test('should handle multiple real-time messages', async ({ page }) => {
    // Wait for connection
    await expect(page.getByText('Connected')).toBeVisible({ timeout: 5000 });

    // Get WebSocket instance
    await page.evaluate(() => {
      const wsInstance = new (window as any).WebSocket('ws://localhost:8765');
      (window as any).testWs = wsInstance;
    });

    // Simulate multiple messages
    const messages = ['Message 1', 'Message 2', 'Message 3'];
    for (const msg of messages) {
      await page.evaluate((message) => {
        (window as any).testWs.simulateMessage(message);
      }, msg);

      // Small delay between messages
      await page.waitForTimeout(100);
    }

    // Verify all messages appear
    for (const msg of messages) {
      await expect(page.getByText(msg)).toBeVisible({ timeout: 5000 });
    }

    // Verify final message count
    await expect(page.getByText('Messages: 3')).toBeVisible();
  });

  test('should send message through WebSocket', async ({ page }) => {
    // Wait for connection
    await expect(page.getByText('Connected')).toBeVisible({ timeout: 5000 });

    // Get WebSocket instance
    await page.evaluate(() => {
      const wsInstance = new (window as any).WebSocket('ws://localhost:8765');
      (window as any).testWs = wsInstance;
    });

    // Fill input and send message
    const input = page.getByPlaceholder('Enter message');
    await input.fill('Test message');

    const sendButton = page.getByRole('button', { name: 'Send' });
    await sendButton.click();

    // Verify message was sent
    const sentMessages = await page.evaluate(() => {
      return (window as any).mockWebSocketMessages;
    });

    expect(sentMessages).toContain('Test message');

    // Verify input cleared
    await expect(input).toHaveValue('');
  });

  test('should handle WebSocket disconnection', async ({ page }) => {
    // Wait for connection
    await expect(page.getByText('Connected')).toBeVisible({ timeout: 5000 });

    // Get WebSocket instance and close it
    await page.evaluate(() => {
      const wsInstance = new (window as any).WebSocket('ws://localhost:8765');
      (window as any).testWs = wsInstance;
      setTimeout(() => {
        wsInstance.close();
      }, 100);
    });

    // Verify status changes to disconnected
    await expect(page.getByText('Disconnected')).toBeVisible({ timeout: 5000 });

    const status = page.locator('#status');
    await expect(status).toHaveAttribute('data-connected', 'false');
  });
